12	)
13	
14	// UtilizationProbe is a thin liveness probe for ds4-server. ds4 deliberately
15	// has no /health, /metrics, or /slots endpoints — see issue #53 / README.
16	// The only signal we can pull from the server is GET /v1/models returning
17	// 200 with the hardcoded "deepseek-v4-flash" entry. Queue depth and active-
18	// request counts must be tracked client-side; the server serializes requests
19	// to a single graph worker (max_concurrency=1) regardless of what clients do,
20	// so synthesizing MaxConcurrency=1 is accurate.
21	type UtilizationProbe struct {
22		baseURL string
23		client  *http.Client
24		cache   utilization.Cache
25	}
26	
27	// NewUtilizationProbe creates a probe for a ds4-server base URL (must end
28	// with /v1 by convention; the probe joins the rest of the path itself).
29	func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
30		if client == nil {
31			client = http.DefaultClient
32		}
33		return &UtilizationProbe{
34			baseURL: baseURL,
35			client:  client,
36		}
37	}
38	
39	// Probe issues GET /v1/models. On 200 with the expected payload shape we
40	// emit MaxConcurrency=1 (ds4-server's hard limit) with everything else as
41	// nil. On any failure we fall back to the prior cached sample, or
42	// utilization.Unknown if we have none.
43	func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
44		if sample, ok := p.probeModels(ctx); ok {
45			return p.cache.Remember(sample)
46		}
47		if stale, ok := p.cache.Stale(); ok {
48			return stale
49		}
50		return utilization.Unknown(utilization.SourceDS4Models)
51	}
52	
53	func (p *UtilizationProbe) probeModels(ctx context.Context) (utilization.EndpointUtilization, bool) {
54		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/v1/models")
55		if err != nil {
56			return utilization.EndpointUtilization{}, false
57		}
58		var payload struct {
59			Data []struct {
60				ID string `json:"id"`
61			} `json:"data"`
62		}
63		if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &payload); err != nil {
64			return utilization.EndpointUtilization{}, false
65		}
66		if len(payload.Data) == 0 {
67			return utilization.EndpointUtilization{}, false
68		}
69		// ds4 serializes everything to a single graph worker. MaxConcurrency=1
70		// is the right backpressure signal for the router; ActiveRequests stays
71		// nil because the server does not expose it.
72		maxConc := 1
73		return utilization.EndpointUtilization{
74			MaxConcurrency: &maxConc,
75			Source:         utilization.SourceDS4Models,
76		}, true
77	}
78	
79	func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
80		req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
81		if err != nil {
82			return "", err
83		}
84		resp, err := p.client.Do(req)
85		if err != nil {
86			return "", err
87		}
88		defer resp.Body.Close()
89		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
90			body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
91			return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
92		}
93		body, err := io.ReadAll(resp.Body)
94		if err != nil {
95			return "", err
96		}
97		return string(body), nil
98	}
