14	// UtilizationProbe queries llama-server observability endpoints and
15	// normalizes them into the shared endpoint utilization shape.
16	type UtilizationProbe struct {
17		baseURL string
18		client  *http.Client
19		cache   utilization.Cache
20	}
21	
22	// NewUtilizationProbe creates a probe for an OpenAI-compatible llama-server
23	// base URL.
24	func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
25		if client == nil {
26			client = http.DefaultClient
27		}
28		return &UtilizationProbe{
29			baseURL: baseURL,
30			client:  client,
31		}
32	}
33	
34	// Probe first tries /metrics on the server root and falls back to /slots when
35	// metrics are unavailable.
36	func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
37		if sample, ok := p.probeMetrics(ctx); ok {
38			return p.cache.Remember(sample)
39		}
40		if sample, ok := p.probeSlots(ctx); ok {
41			return p.cache.Remember(sample)
42		}
43		if stale, ok := p.cache.Stale(); ok {
44			return stale
45		}
46		return utilization.Unknown(utilization.SourceLlamaMetrics)
47	}
48	
49	func (p *UtilizationProbe) probeMetrics(ctx context.Context) (utilization.EndpointUtilization, bool) {
50		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
51		if err != nil {
52			return utilization.EndpointUtilization{}, false
53		}
54	
55		processing, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_processing")
56		if !ok {
57			return utilization.EndpointUtilization{}, false
58		}
59		deferred, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_deferred")
60		if !ok {
61			return utilization.EndpointUtilization{}, false
62		}
63	
64		sample := utilization.EndpointUtilization{
65			ActiveRequests: utilization.Int(int(processing)),
66			QueuedRequests: utilization.Int(int(deferred)),
67			Source:         utilization.SourceLlamaMetrics,
68		}
69		if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:kv_cache_usage_ratio"); ok {
70			sample.CacheUsage = utilization.Float64(cacheUsage)
71		}
72		return sample, true
73	}
74	
75	func (p *UtilizationProbe) probeSlots(ctx context.Context) (utilization.EndpointUtilization, bool) {
76		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/slots")
77		if err != nil {
78			return utilization.EndpointUtilization{}, false
79		}
80	
81		var arrayPayload []map[string]any
82		slots := 0
83		processing := 0
84		if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &arrayPayload); err == nil {
85			slots = len(arrayPayload)
86			for _, slot := range arrayPayload {
87				if isProcessing(slot) {
88					processing++
89				}
90			}
91			return p.slotSample(processing, slots), true
92		}
93	
94		var objectPayload struct {
95			Slots     []map[string]any `json:"slots"`
96			SlotCount int              `json:"slot_count"`
97		}
98		if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &objectPayload); err != nil {
99			return utilization.EndpointUtilization{}, false
100		}
101		slots = objectPayload.SlotCount
102		if slots == 0 {
103			slots = len(objectPayload.Slots)
104		}
105		for _, slot := range objectPayload.Slots {
106			if isProcessing(slot) {
107				processing++
108			}
109		}
110		return p.slotSample(processing, slots), true
111	}
112	
113	func (p *UtilizationProbe) slotSample(processing, slots int) utilization.EndpointUtilization {
114		sample := utilization.EndpointUtilization{
115			ActiveRequests: utilization.Int(processing),
116			Source:         utilization.SourceLlamaSlots,
117		}
118		if slots > 0 {
119			sample.MaxConcurrency = utilization.Int(slots)
120			occupancy := float64(processing) / float64(slots)
121			sample.CacheUsage = utilization.Float64(occupancy)
122		}
123		return sample
124	}
125	
126	func isProcessing(slot map[string]any) bool {
127		processing, _ := slot["is_processing"].(bool)
128		return processing
129	}
130	
