150	// configured model or when discovery has already run.
151	func (p *Provider) EnsureDiscovered(ctx context.Context) error {
152		if p.model != "" {
153			return nil
154		}
155		_, err := p.resolveModel(ctx)
156		return err
157	}
158	
159	// resolveModel returns the model to use for a request. If the provider was
160	// configured without a model it queries /v1/models once, ranks results, and
161	// caches both the full list and the selected model.
162	// Subsequent calls return the cached value without hitting the network.
163	func (p *Provider) resolveModel(ctx context.Context) (string, error) {
164		if p.model != "" {
165			return p.model, nil
166		}
167		p.discoverOnce.Do(func() {
168			candidates, err := DiscoverModels(ctx, p.baseURL, p.apiKey)
169			if err != nil {
170				p.discoverErr = err
171				return
172			}
173			ranked, err := RankModels(candidates, p.knownModels, p.modelPattern)
174			if err != nil {
175				p.discoverErr = err
176				return
177			}
178			p.discoveredModels = ranked
179			selected := SelectModel(ranked)
180			if selected == "" {
181				p.discoverErr = fmt.Errorf("openai: no models returned by %s/models", p.baseURL)
182				return
183			}
184			p.model = selected
185		})
186		return p.model, p.discoverErr
187	}
