189	func (p *Provider) Chat(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (agent.Response, error) {
190		model, err := p.resolveModel(ctx)
191		if err != nil {
192			return agent.Response{}, err
193		}
194		if opts.Model != "" {
195			model = opts.Model
196		}
197	
198		reqOpts, err := p.compatRequestOptions(model, opts)
199		if err != nil {
200			return agent.Response{}, err
201		}
202	
203		result, err := p.client.Chat(ctx, model, messages, tools, reqOpts)
204		if err != nil {
205			return agent.Response{}, fmt.Errorf("openai: %w", err)
206		}
207	
208		resp := agent.Response{
209			Model:        result.Model,
210			Content:      result.Content,
211			FinishReason: result.FinishReason,
212			ToolCalls:    result.ToolCalls,
213			Usage:        result.Usage,
214		}
215		resp.Attempt = p.attemptMetadata(model, result.Model, &agent.CostAttribution{
216			Source: agent.CostSourceUnknown,
217		})
218		if cost := p.costAttribution(result.RawUsage); cost != nil {
219			resp.Attempt.Cost = cost
220		}
221		return resp, nil
222	}
