236	// ChatStream implements agent.StreamingProvider for token-level streaming.
237	func (p *Provider) ChatStream(ctx context.Context, messages []agent.Message, tools []agent.ToolDef, opts agent.Options) (<-chan agent.StreamDelta, error) {
238		model, err := p.resolveModel(ctx)
239		if err != nil {
240			return nil, err
241		}
242		if opts.Model != "" {
243			model = opts.Model
244		}
245	
246		reqOpts, err := p.compatRequestOptions(model, opts)
247		if err != nil {
248			return nil, err
249		}
