345	// reasoningRequestOptions builds per-request options. For thinking models
346	// (Qwen3, DeepSeek-R1 etc.) apply provider-specific non-standard body fields
347	// only when the concrete provider declares the matching wire support.
348	func (p *Provider) reasoningRequestOptions(model string, opts agent.Options) ([]option.RequestOption, error) {
349		policy, err := reasoningpolicy.Parse(opts.Reasoning)
350		if err != nil {
351			return nil, err
352		}
353		explicitRequest := policy.IsSet()
354		if !explicitRequest {
355			policy, err = reasoningpolicy.Parse(p.reasoningDefault)
356			if err != nil {
357				return nil, err
358			}
359		}
360	
361		if !policy.IsSet() || policy.Kind == reasoningpolicy.KindAuto {
362			return nil, nil
363		}
364	
365		// Catalog reasoning_wire metadata gates the wire shape before any
366		// provider-specific encoding runs. Models flagged as reasoning_wire=none
367		// have no reasoning surface at all; an explicit non-off request is a
368		// catalog/wire mismatch and must surface as an error rather than be
369		// silently dropped. Models flagged as reasoning_wire=model_id encode the
370		// reasoning level in the model name (e.g. fixed-variant Qwen3.6) and the
371		// upstream endpoint cannot honor an external reasoning toggle, so the
372		// reasoning field must be stripped from the wire body.
373		catalogWire := p.modelReasoningWireFor(model)
374		switch catalogWire {
375		case "none":
376			if explicitRequest && !policy.IsExplicitOff() {
377				return nil, fmt.Errorf("openai: model %q has reasoning_wire=none; explicit reasoning=%q is not supported", model, policy.Value)
378			}
379			return nil, nil
380		case "model_id":
381			return nil, nil
382		}
383	
384		if !p.SupportsThinking() {
385			if policy.IsExplicitOff() {
386				return nil, nil
387			}
388			if explicitRequest {
389				return nil, fmt.Errorf("openai: reasoning=%q is not supported by provider type %q", policy.Value, p.providerSystem)
390			}
391			return nil, nil
392		}
393	
394		if policy.IsExplicitOff() {
395			switch p.thinkingWireFormat() {
