1	package utilization
2	
3	import (
4		"net/url"
5		"strconv"
6		"strings"
7		"sync"
8		"time"
9	)
10	
11	// Source identifies the probe path that produced a utilization sample.
12	type Source string
13	
14	const (
15		SourceUnknown        Source = "unknown"
16		SourceOMLXStatus     Source = "omlx.status"
17		SourceVLLMMetrics    Source = "vllm.metrics"
18		SourceLlamaMetrics   Source = "llama-server.metrics"
19		SourceLlamaSlots     Source = "llama-server.slots"
20		SourceRapidMLXStatus Source = "rapid-mlx.status"
21		SourceDS4Models      Source = "ds4.models"
22	)
23	
24	// Freshness describes whether a sample was observed just now, reused after a
25	// failed probe, or has no known prior observation.
26	type Freshness string
27	
28	const (
29		FreshnessFresh   Freshness = "fresh"
30		FreshnessStale   Freshness = "stale"
31		FreshnessUnknown Freshness = "unknown"
32	)
33	
34	// EndpointUtilization is the normalized utilization shape shared by local
35	// provider probes.
36	type EndpointUtilization struct {
37		ActiveRequests         *int
38		QueuedRequests         *int
39		CacheUsage             *float64
40		MaxConcurrency         *int
41		TotalPromptTokens      *int
42		TotalCompletionTokens  *int
43		CacheHitType           *string
44		CachedTokens           *int
45		GeneratedTokens        *int
46		ActiveRequestPhase     *string
47		TTFTSeconds            *float64
48		TokensPerSecond        *float64
49		MetalActiveMemoryBytes *int64
50		MetalPeakMemoryBytes   *int64
51		MetalCacheMemoryBytes  *int64
52		Source                 Source
53		Freshness              Freshness
54		ObservedAt             time.Time
55	}
56	
57	// Cache preserves the most recent successful sample so probe failures can
58	// return stale utilization instead of surfacing hard endpoint unavailability.
59	type Cache struct {
60		mu   sync.Mutex
61		last *EndpointUtilization
62	}
63	
64	// Remember stores a fresh sample and returns a normalized copy with fresh
65	// freshness and an observed timestamp.
66	func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
67		c.mu.Lock()
68		defer c.mu.Unlock()
69	
70		now := time.Now().UTC()
71		sample.Freshness = FreshnessFresh
72		sample.ObservedAt = now
73		stored := clone(sample)
74		c.last = &stored
75		return stored
76	}
77	
78	// Stale returns the last successful sample marked stale. The boolean reports
79	// whether a previous sample existed.
80	func (c *Cache) Stale() (EndpointUtilization, bool) {
81		c.mu.Lock()
82		defer c.mu.Unlock()
83	
84		if c.last == nil {
85			return EndpointUtilization{}, false
86		}
87		stale := clone(*c.last)
88		stale.Freshness = FreshnessStale
89		return stale, true
90	}
91	
92	// Unknown returns a sample with unknown freshness and no numeric values.
93	func Unknown(source Source) EndpointUtilization {
94		return EndpointUtilization{
95			Source:    source,
96			Freshness: FreshnessUnknown,
97		}
98	}
