143	// ParsePrometheusMetricValue returns the first numeric value for metric from
144	// a Prometheus-style plaintext metrics body.
145	func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
146		for _, line := range strings.Split(body, "\n") {
