141		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
142			body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
143			return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
144		}
145		body, err := io.ReadAll(resp.Body)
146		if err != nil {
