148		}
149		return string(body), nil
150	}
151

120	// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
121	// base URL while preserving the scheme, host, and any prefix path.
122	func ServerRoot(baseURL string) string {
123		trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
124		if trimmed == "" {
125			return ""
126		}
127	
128		parsed, err := url.Parse(trimmed)
129		if err != nil {
130			return strings.TrimSuffix(trimmed, "/v1")
131		}
132	
133		parsed.Fragment = ""
134		parsed.RawQuery = ""
135		path := strings.TrimRight(parsed.Path, "/")
136		if strings.HasSuffix(path, "/v1") {
137			path = strings.TrimSuffix(path, "/v1")
138		}
139		parsed.Path = path
140		return strings.TrimRight(parsed.String(), "/")
141	}
